using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

var endpoint = builder.Configuration["AI:Endpoint"] is string ep ? new Uri(ep) : null;

var clientOptions = new OpenAIClientOptions();
if (endpoint is not null)
{
    clientOptions.Endpoint = endpoint;
}

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAI.Chat.ChatClient(modelId, apiKey, clientOptions)
        .AsIChatClient()));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notebook = new Notebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            return WebSearchTool.SearchAsync(query);
        },
        "web_search",
        "Search the web for information on a topic. Returns a list of results with titles, snippets, and URLs."),

    AIFunctionFactory.Create(
        ([Description("Title of the note")] string title,
         [Description("Content of the note")] string content) =>
        {
            Console.WriteLine($"  📝 Saving note: \"{title}\"");
            notebook.AddNote(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Save a research note with a title and content. Use this to record important findings."),

    AIFunctionFactory.Create(
        () =>
        {
            Console.WriteLine("  📖 Reading all notes...");
            return notebook.GetAllNotes();
        },
        "read_notes",
        "Read all saved research notes."),
};

var agent = chatClient.AsAIAgent(
    instructions: """
        You are a thorough research agent. When given a topic:
        1. Search the web for relevant information using multiple targeted queries.
        2. Save key findings as notes using the save_note tool.
        3. After gathering enough information, read your notes and produce a clear, well-structured summary.
        Be methodical: search, take notes, then summarize. Always cite sources.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine("  🔬 Research Agent");
Console.WriteLine("═══════════════════════════════════════");
Console.Write("\nEnter a research topic (or 'quit'): ");
var topic = Console.ReadLine()?.Trim();

while (!string.IsNullOrEmpty(topic) && !topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    Console.WriteLine($"\n▶ Researching: {topic}\n");

    var session = await agent.CreateSessionAsync($"research-{Guid.NewGuid():N}");

    var runOptions = new ChatClientAgentRunOptions
    {
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        },
    };

    try
    {
        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic thoroughly. Search the web, take notes on key findings, then provide a comprehensive summary.\n\nTopic: {topic}",
            session,
            runOptions))
        {
            if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
            {
                Console.Write(update.Text);
            }
        }

        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
    }

    if (notebook.Notes.Count > 0)
    {
        Console.WriteLine($"\n📋 {notebook.Notes.Count} note(s) taken during research.");
        notebook.Clear();
    }

    Console.Write("\nEnter a research topic (or 'quit'): ");
    topic = Console.ReadLine()?.Trim();
}

Console.WriteLine("Goodbye!");

// --- Supporting types ---

/// <summary>Simulated web search returning plausible results for any query.</summary>
static class WebSearchTool
{
    public static Task<IReadOnlyList<SearchResult>> SearchAsync(string query)
    {
        // In production, replace with a real search API (Bing, Google, Tavily, etc.)
        var results = new List<SearchResult>
        {
            new($"Overview of {query}",
                $"Comprehensive overview covering the key aspects of {query}, including history, current state, and future outlook.",
                $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}"),
            new($"{query} - Latest Research and Developments",
                $"Recent studies and breakthroughs related to {query}. Experts discuss implications and next steps.",
                $"https://research.example.com/{Uri.EscapeDataString(query)}"),
            new($"Understanding {query}: A Deep Dive",
                $"An in-depth analysis of {query} examining multiple perspectives, data sources, and expert opinions.",
                $"https://deepdive.example.com/{Uri.EscapeDataString(query)}"),
        };

        return Task.FromResult<IReadOnlyList<SearchResult>>(results);
    }
}

record SearchResult(string Title, string Snippet, string Url);

/// <summary>Simple notebook for collecting research notes.</summary>
class Notebook
{
    public List<Note> Notes { get; } = [];

    public void AddNote(string title, string content)
        => Notes.Add(new Note(title, content, DateTime.UtcNow));

    public string GetAllNotes()
        => Notes.Count == 0
            ? "No notes saved yet."
            : string.Join("\n\n", Notes.Select((n, i) =>
                $"[{i + 1}] {n.Title} ({n.Timestamp:u})\n{n.Content}"));

    public void Clear() => Notes.Clear();
}

